draw:
var kap = p.kappa;
var sig = p.sigma;            // uC/m^2 free surface charge
var eps0 = 8.854e-12;
var E0 = sig * 1e-6 / eps0;   // V/m
var Ein = E0 / kap;
var sigb = sig * (1 - 1 / kap);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

var L = W * 0.60, x0 = (W - L) / 2;
var yTop = H * 0.26, yBot = H * 0.80;
var gap = yBot - yTop;
var sTop = yTop + gap * 0.22, sBot = yBot - gap * 0.22;

// plates
ctx.fillStyle = C.figure;
ctx.fillRect(x0, yTop - 9, L, 9);
ctx.fillRect(x0, yBot, L, 9);
ctx.fillStyle = C.ink;
ctx.fillText("free charge  +Q  on the top plate", x0, yTop - 16);
ctx.fillText("free charge  -Q  on the bottom plate", x0, yBot + 24);

// slab
ctx.globalAlpha = 0.35;
ctx.fillStyle = C.faint;
ctx.fillRect(x0, sTop, L, sBot - sTop);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.strokeRect(x0, sTop, L, sBot - sTop);
ctx.fillStyle = C.ink;
ctx.fillText("dielectric, kappa = " + kap.toFixed(1), x0 + 6, (sTop + sBot) / 2 + 4);

// bound charge marks, fading with (1 - 1/kappa)
var frac = 1 - 1 / kap;
ctx.globalAlpha = 0.25 + 0.75 * frac;
ctx.fillStyle = C.accent;
var nb = 9;
for (var i = 0; i < nb; i++) {
  var bx = x0 + L * (i + 0.5) / nb;
  ctx.fillText("-", bx - 2, sTop - 4);
  ctx.fillText("+", bx - 3, sBot + 12);
}
ctx.globalAlpha = 1;
ctx.fillStyle = C.accent;
ctx.fillText("bound  -", x0 + L + 6, sTop + 2);
ctx.fillText("bound  +", x0 + L + 6, sBot + 4);

// field lines: n outside, fewer inside by 1/kappa
var n = 8;
var inside = Math.max(1, Math.round(n / kap));
ctx.lineWidth = 1.6;
for (var j = 0; j < n; j++) {
  var fx = x0 + L * (j + 0.5) / n;
  ctx.strokeStyle = C.figure;
  ctx.beginPath(); ctx.moveTo(fx, yTop); ctx.lineTo(fx, sTop); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(fx, sBot); ctx.lineTo(fx, yBot); ctx.stroke();
  if (j < inside) {
    ctx.strokeStyle = C.accent;
    ctx.beginPath(); ctx.moveTo(fx, sTop); ctx.lineTo(fx, sBot); ctx.stroke();
    // arrowhead
    var my = (sTop + sBot) / 2;
    ctx.beginPath(); ctx.moveTo(fx, my + 5); ctx.lineTo(fx - 3, my - 1); ctx.lineTo(fx + 3, my - 1); ctx.closePath();
    ctx.fillStyle = C.accent; ctx.fill();
  }
}
ctx.fillStyle = C.ink;
ctx.fillText("E0 in the vacuum gaps", x0, yTop + gap * 0.14);

out.note = "E0 = " + (E0 / 1e6).toFixed(2) + " MV/m,  E inside = " + (Ein / 1e6).toFixed(2) +
  " MV/m,  bound sigma = " + sigb.toFixed(2) + " uC/m^2 of the " + sig.toFixed(1) + " uC/m^2 free";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.lineWidth = 1.5;

var pad = W * 0.06;
var panelW = (W - 3 * pad) / 2;
var top = H * 0.22, bot = H * 0.68;

// ---- left panel: stacked layers (series) ----
var ax = pad;
ctx.fillStyle = C.ink;
ctx.fillText("Stacked layers: same Q, voltages add", ax, H * 0.13);
ctx.fillStyle = C.figure;
ctx.fillRect(ax, top - 8, panelW, 8);
ctx.fillRect(ax, bot, panelW, 8);
var mid = top + (bot - top) * 0.45;
ctx.globalAlpha = 0.35; ctx.fillStyle = C.faint;
ctx.fillRect(ax, top, panelW, mid - top);
ctx.globalAlpha = 0.18;
ctx.fillRect(ax, mid, panelW, bot - mid);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.strokeRect(ax, top, panelW, mid - top);
ctx.strokeRect(ax, mid, panelW, bot - mid);
ctx.fillStyle = C.ink;
ctx.fillText("k1, thickness d1", ax + 6, (top + mid) / 2 + 4);
ctx.fillText("k2, thickness d2", ax + 6, (mid + bot) / 2 + 4);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(ax + panelW + 10, top); ctx.lineTo(ax + panelW + 10, bot); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("V = V1 + V2", ax + panelW - 4, bot + 22);
ctx.fillStyle = C.ink;
ctx.fillText("1/C = d1/(k1 e0 A) + d2/(k2 e0 A)", ax, bot + 40);

// ---- right panel: side by side (parallel) ----
var bx = 2 * pad + panelW;
ctx.fillStyle = C.ink;
ctx.fillText("Side by side: same V, charges add", bx, H * 0.13);
ctx.fillStyle = C.figure;
ctx.fillRect(bx, top - 8, panelW, 8);
ctx.fillRect(bx, bot, panelW, 8);
var split = bx + panelW * 0.5;
ctx.globalAlpha = 0.35; ctx.fillStyle = C.faint;
ctx.fillRect(bx, top, panelW * 0.5, bot - top);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.strokeRect(bx, top, panelW * 0.5, bot - top);
ctx.strokeRect(split, top, panelW * 0.5, bot - top);
ctx.fillStyle = C.ink;
ctx.fillText("k, area A1", bx + 4, (top + bot) / 2 + 4);
ctx.fillText("air, A2", split + 4, (top + bot) / 2 + 4);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(bx + 12, top); ctx.lineTo(bx + 12, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(split + 12, top); ctx.lineTo(split + 12, bot); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("same V across both", bx, bot + 22);
ctx.fillStyle = C.ink;
ctx.fillText("C = k e0 A1/d + e0 A2/d", bx, bot + 40);

out.note = "Cut along the field lines and the pieces are in parallel; cut across them and the pieces are in series.";

var eps0 = 8.854e-12;
var kap = p.kappa, V = p.volts, xcm = p.x;
var Lcm = 10.0, wcm = 8.0, dmm = 0.50;
var Lm = Lcm / 100, wm = wcm / 100, dm = dmm / 1000;
var xm = xcm / 100;
var Cx = eps0 * wm * (Lm - xm + kap * xm) / dm;   // farads
var F = eps0 * wm * (kap - 1) * V * V / (2 * dm); // newtons, constant in x

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.lineWidth = 1.5;

var px0 = W * 0.10, plateL = W * 0.62;
var yTop = H * 0.20, yBot = H * 0.40;

// plates
ctx.fillStyle = C.figure;
ctx.fillRect(px0, yTop - 7, plateL, 7);
ctx.fillRect(px0, yBot, plateL, 7);

// slab, inserted a fraction x/L from the left
var frac = xm / Lm;
var slabW = plateL * frac;
ctx.globalAlpha = 0.35; ctx.fillStyle = C.faint;
ctx.fillRect(px0, yTop, slabW, yBot - yTop);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.strokeRect(px0 - plateL * 0.34, yTop, plateL * 0.34 + slabW, yBot - yTop);
ctx.fillStyle = C.ink;
ctx.fillText("slab, kappa = " + kap.toFixed(1), px0 - plateL * 0.30, (yTop + yBot) / 2 + 4);

// pulling force arrow, dashes crawl with t
ctx.strokeStyle = C.accent;
ctx.setLineDash([6, 4]);
ctx.lineDashOffset = -(t * 30) % 10;
var ay = (yTop + yBot) / 2;
ctx.beginPath(); ctx.moveTo(px0 + slabW + 8, ay); ctx.lineTo(px0 + slabW + 54, ay); ctx.stroke();
ctx.setLineDash([]);
ctx.beginPath();
ctx.moveTo(px0 + slabW + 4, ay); ctx.lineTo(px0 + slabW + 16, ay - 5); ctx.lineTo(px0 + slabW + 16, ay + 5);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.fillText("F pulls the slab in", px0 + slabW + 20, ay - 10);

// fringing note + edge marker
ctx.fillStyle = C.ink;
ctx.fillText("x", px0 + slabW / 2 - 3, yTop - 12);
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(px0 + slabW, yTop - 20); ctx.lineTo(px0 + slabW, yBot + 20); ctx.stroke();
ctx.setLineDash([]);

// battery symbol
ctx.strokeStyle = C.figure;
var bx = px0 + plateL + 24;
ctx.beginPath(); ctx.moveTo(px0 + plateL, yTop - 4); ctx.lineTo(bx, yTop - 4);
ctx.lineTo(bx, (yTop + yBot) / 2 - 8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 9, (yTop + yBot) / 2 - 8); ctx.lineTo(bx + 9, (yTop + yBot) / 2 - 8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 4, (yTop + yBot) / 2); ctx.lineTo(bx + 4, (yTop + yBot) / 2); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx, (yTop + yBot) / 2); ctx.lineTo(bx, yBot + 4); ctx.lineTo(px0 + plateL, yBot + 4); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(V.toFixed(0) + " V", bx + 12, (yTop + yBot) / 2 + 4);

// C(x) graph
var gx0 = W * 0.12, gx1 = W * 0.80, gy0 = H * 0.92, gy1 = H * 0.56;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx1, gy0); ctx.stroke();
ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("x (cm)", gx1 - 34, gy0 + 16);
ctx.fillText("C", gx0 - 12, gy1 + 2);

var Cmin = eps0 * wm * Lm / dm;
var Cmax = eps0 * wm * kap * Lm / dm;
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var i = 0; i <= 40; i++) {
  var xx = Lm * i / 40;
  var cc = eps0 * wm * (Lm - xx + kap * xx) / dm;
  var gx = gx0 + (gx1 - gx0) * (i / 40);
  var gy = gy0 - (gy0 - gy1) * (cc - Cmin) / (Cmax - Cmin + 1e-18);
  i === 0 ? ctx.moveTo(gx, gy) : ctx.lineTo(gx, gy);
}
ctx.stroke();
var mx = gx0 + (gx1 - gx0) * frac;
var my2 = gy0 - (gy0 - gy1) * (Cx - Cmin) / (Cmax - Cmin + 1e-18);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(mx, my2, 4, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("C rises in a straight line with x, so dC/dx is the same everywhere", gx0, gy1 - 8);

out.note = "C = " + (Cx * 1e12).toFixed(1) + " pF,  dC/dx = " +
  (eps0 * wm * (kap - 1) / dm * 1e12 / 100).toFixed(2) + " pF/cm,  F = " + (F * 1000).toFixed(3) + " mN (same at every x)";
